import{_ as n,H as e,f as a,i}from"./chunks/framework.BH2BK_3i.js";const k=JSON.parse('{"title":"10 | 网络篇：通过Ingress提供URL访问","description":"","frontmatter":{},"headers":[{"level":2,"title":"认识 Ingress","slug":"认识-ingress","link":"#认识-ingress","children":[]},{"level":2,"title":"安装 Ingress Controller","slug":"安装-ingress-controller","link":"#安装-ingress-controller","children":[]},{"level":2,"title":"创建 Ingress 规则","slug":"创建-ingress-规则","link":"#创建-ingress-规则","children":[]},{"level":2,"title":"访问 Ingress Controller","slug":"访问-ingress-controller","link":"#访问-ingress-controller","children":[]},{"level":2,"title":"配置 HTTPS","slug":"配置-https","link":"#配置-https","children":[{"level":3,"title":"第一步：生成证书文件","slug":"第一步-生成证书文件","link":"#第一步-生成证书文件","children":[]},{"level":3,"title":"第二步：部署证书 Secret","slug":"第二步-部署证书-secret","link":"#第二步-部署证书-secret","children":[]},{"level":3,"title":"第三步：在 Ingress 的 YAML 文件中增加 tls 配置","slug":"第三步-在-ingress-的-yaml-文件中增加-tls-配置","link":"#第三步-在-ingress-的-yaml-文件中增加-tls-配置","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"零基础拿下云原生CKA认证/10｜网络篇：通过Ingress提供URL访问.md","filePath":"零基础拿下云原生CKA认证/10｜网络篇：通过Ingress提供URL访问.md","lastUpdated":1795561650000}'),l={name:"零基础拿下云原生CKA认证/10｜网络篇：通过Ingress提供URL访问.md"};function p(t,s,r,o,g,c){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="_10-网络篇-通过ingress提供url访问" tabindex="-1">10 | 网络篇：通过Ingress提供URL访问 <a class="header-anchor" href="#_10-网络篇-通过ingress提供url访问" aria-label="Permalink to &quot;10 | 网络篇：通过Ingress提供URL访问&quot;">​</a></h1><p>你好，我是雪飞。</p><p>上节课我介绍了 Service，它主要负责集群的服务发现和负载均衡。对于来自集群外部的访问，可以使用 NodePort 或者 LoadBalance 类型的 Service，K8s 会自动绑定集群节点的端口号，通过 “&lt; 节点 IP&gt;:&lt; 节点端口 &gt;” 来访问 Service，从而最终访问到 Service 代理的应用Pod。但是在微服务架构中，由于集群中通常运行着多个需要暴露到外部访问的应用，如果每个应用都通过这种 Service 绑定节点端口的方式访问，可能会导致节点端口管理变得复杂且存在安全隐患。</p><p>此外，Service 是通过 IP 地址和端口来提供网络访问，这是一种四层的负载均衡，我们在实际开发项目中，更多时候是通过 URL 地址来访问应用，这需要七层的负载均衡，例如我们常用的 Nginx Web 服务就可以使用域名来代理到不同的网络应用。</p><ul><li>负载均衡可以分为四层和七层，分别对应 OSI 模型的传输层和应用层。四层负载均衡工作在传输层，负责处理 TCP/UDP 协议。根据源 IP、源端口号以及目的 IP和目的端口号来转发流量到应用服务器。而七层负载均衡工作在应用层，可以根据 HTTP、HTTPS、DNS 等应用层协议来进行负载均衡，还可以基于 URL、浏览器类型、语言等内容来制定负载均衡策略。</li></ul><p>所以为了解决 Service 处理集群外部访问请求的局限性，K8s 提供了 Ingress 资源对象。Ingress 是一种七层的负载均衡，可以实现高级路由策略，从而更高效地管理集群外部流量。</p><h2 id="认识-ingress" tabindex="-1">认识 Ingress <a class="header-anchor" href="#认识-ingress" aria-label="Permalink to &quot;认识 Ingress&quot;">​</a></h2><p>Ingress 通过定义一系列的路由规则，允许你将集群外部的 HTTP/HTTPS 请求分配到集群内不同的 Service 上。所以 Ingress 的机制相当于是在 Service 上又加了一层规则，它获取到用户访问的域名和路径，然后根据规则把访问请求转发到了对应的 Service 上，然后再由Service 把流量转发到具体的应用 Pod。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/1.png" alt=""></a></p><p>Ingress 由三个核心组件组成，Ingress、Ingress Controller 和 Ingress Class。</p><p>Ingress 是一组路由规则（Rules）。每个规则定义了如何处理进入集群的访问请求，包含主机域名（Host）和路径列表（Path）。路径列表定义了基于 URL 路径的请求分发规则，每个路径都关联一个后端服务（Backend），后端服务就是实际处理请求的 Service，包含了 Service 的名称（ServiceName）和端口（ServicePort）。Ingress 本身并不直接处理流量，它的功能需要依赖于 Ingress Controller。</p><p>Ingress Controller 是负责实现 Ingress 规则的组件，它负责监听 Ingress 的变化，并确保路由规则被正确应用。K8s 官方并没有实现自己的 Ingress Controller，而是定义了 IngressController 的实现标准，很多第三方公司都基于标准实现了自己的 Ingress Controller，目前我们最常用的就是大名鼎鼎的 Nginx Ingress Controller，你也可以使用其他公司实现的Ingress Controller。</p><p>Ingress Class 是夹在 Ingress 和 Ingress Controller 中间的一个层级，解除了 Ingress 和Ingress Controller 的强绑定关系。在 Ingress 中指定要使用的 Ingress Class，而在 IngressClass 中可以指定要使用的 Ingress Controller 以及设置一些额外的配置。</p><p>总之，Ingress 类似法律条文，而 Ingress Controller 则是法官。当集群外部请求到达 IngressController 时，Ingress Controller 会根据 Ingress 规则中定义的主机域名和路径将请求发送到对应的 Service。</p><h2 id="安装-ingress-controller" tabindex="-1">安装 Ingress Controller <a class="header-anchor" href="#安装-ingress-controller" aria-label="Permalink to &quot;安装 Ingress Controller&quot;">​</a></h2><p>由于 K8s 集群中没有默认安装 Ingress Controller。我们需要先在集群中部署 IngressController，这里我选择常用的 Nginx Ingress Controller。（参考官方文档）</p><p>Nginx Ingress Controller 组件也是部署在 K8s 集群中，我们可以直接用官网提供的 YAML 文件部署。但是国内无法直接下载镜像，所以我们需要先下载 YAML 文件，找到对应镜像位置，然后替换成国内阿里云的镜像库。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 通过 wget 命令下载 Nginx Ingress Controller 部署文件</span></span>
<span class="line"><span>[root@k8s-master ~]# wget https://raw.githubusercontent.com/kubernetes/ingress-ng</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>HTTP request sent, awaiting response... 200 OK</span></span>
<span class="line"><span>Length: 16136 (16K) [text/plain]</span></span>
<span class="line"><span>Saving to: ‘deploy.yaml’</span></span>
<span class="line"><span>100%[============================================================================</span></span>
<span class="line"><span>2024-06-23 19:11:45 (15.6 KB/s) - ‘deploy.yaml’ saved [16136/16136]</span></span></code></pre></div><p>通过 vi 编辑器编辑 YAML 文件（deploy.yaml），把 registry.k8s.io 的镜像替换成如下阿里云镜像库的镜像：</p><ul><li><p>registry.cn-hangzhou.aliyuncs.com/google_containers/nginx-ingress-controller:v1.10.1</p></li><li><p>registry.cn-hangzhou.aliyuncs.com/google_containers/kube-webhook-certgen:v1.4.1</p></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# vi deploy.yaml</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>446      # image: registry.k8s.io/ingress-nginx/controller:v1.10.1@sha256:e24f39d</span></span>
<span class="line"><span>447      image:registry.cn-hangzhou.aliyuncs.com/google_containers/nginx-ingress-</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>548      # image: registry.k8s.io/ingress-nginx/kube-webhook-certgen:v1.4.1@sha25</span></span>
<span class="line"><span>549      image: registry.cn-hangzhou.aliyuncs.com/google_containers/kube-webhook-</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>602      # image: registry.k8s.io/ingress-nginx/kube-webhook-certgen:v1.4.1@sha25</span></span>
<span class="line"><span>603      image: registry.cn-hangzhou.aliyuncs.com/google_containers/kube-webhook-</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>保存后，使用 “kubectl apply” 命令部署，等 Nginx Ingress Controller 部署完成，查看 IngressController 的 Deployment 和 Service，注意需要加上 ingress-nginx 命名空间，最后再查看一下 Ingress Class。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl apply -f deploy.yaml</span></span>
<span class="line"><span>[root@k8s-master ~]# kubectl get deployment,svc -n ingress-nginx</span></span>
<span class="line"><span>NAME                                       READY   UP-TO-DATE   AVAILABLE   AGE</span></span>
<span class="line"><span>deployment.apps/ingress-nginx-controller   1/1     1            1           11m</span></span>
<span class="line"><span>NAME                                         TYPE           CLUSTER-IP       EXTE</span></span>
<span class="line"><span>service/ingress-nginx-controller             LoadBalancer   10.106.241.178   &lt;​pen</span></span>
<span class="line"><span>service/ingress-nginx-controller-admission   ClusterIP      10.100.108.214   &lt;​non</span></span>
<span class="line"><span>[root@k8s-master ~]# kubectl get ingressclass  # 查看 Ingress Class</span></span>
<span class="line"><span>NAME    CONTROLLER             PARAMETERS   AGE</span></span>
<span class="line"><span>nginx   k8s.io/ingress-nginx   &lt;​none&gt;       11m</span></span></code></pre></div><p>可以看到 Nginx Ingress Controller 是通过 Deployment 来部署的，同时也创建了一个 Service和一个 Ingress Class，这个 Ingress Class 指向 Nginx（Nginx Ingress Controller 部署的控制器名称）。下面我们就可以在创建 Ingress 规则时使用这个 Ingress Class。</p><h2 id="创建-ingress-规则" tabindex="-1">创建 Ingress 规则 <a class="header-anchor" href="#创建-ingress-规则" aria-label="Permalink to &quot;创建 Ingress 规则&quot;">​</a></h2><p>使用 Ingress 规则的前提是已经部署好了应用的 Deployment 和其中的 Pod ，同时也对 Pod创建了 Service 网络访问代理。我们上节课已经搭建好了相关环境，所以下面的例子是创建一个 Ingress 规则，将集群外部访问 myapp.address.com 域名以及访问路径为 “/” 的请求都转发到之前创建好的名称为 my-service 的 Service 中，然后再经过 my-service 转发到具体的应用Pod 中去处理。</p><p>准备好了 Ingress Controller 和 Ingress Class，就可以开始创建 Ingress 规则了。使用 kubectl命令或 YAML 文件创建 Ingress 规则。</p><p>使用 kubectl 命令</p><p>使用 “kubectl create ingress” 命令创建一条名称为 “my-ingress” 的规则。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl create ingress my-ingress --class=nginx --rule=&quot;myap</span></span>
<span class="line"><span>ingress.networking.k8s.io/my-ingress created</span></span></code></pre></div><ul><li><p>–class：指定了要使用的 Ingress Class 为 nginx。</p></li><li><p>–rule：指定了具体的路由规则，“myapp.address.com” 是主机域名，/* 是匹配路径，my-service 是该规则转发到后端的 Service 名称，80 是 Service 的端口号。</p></li></ul><p>通过命令可以快速生成一条简单的 Ingress 规则，但是在实际项目中，Ingress 规则通常比较复杂，因此我们通常使用 YAML 文件来配置 Ingress 规则。</p><p>Ingress 的 YAML 文件（my-ingress.yaml）如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># my-ingress.yaml</span></span>
<span class="line"><span>apiVersion: networking.k8s.io/v1</span></span>
<span class="line"><span>kind: Ingress</span></span>
<span class="line"><span>metadata:</span></span>
<span class="line"><span> name: my-ingress</span></span>
<span class="line"><span> namespace: default</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> ingressClassName: nginx</span></span>
<span class="line"><span> rules:</span></span>
<span class="line"><span> - host: myapp.address.com</span></span>
<span class="line"><span>   http:</span></span>
<span class="line"><span>     paths:</span></span>
<span class="line"><span>     - path: /</span></span>
<span class="line"><span>       pathType: Prefix</span></span>
<span class="line"><span>       backend:</span></span>
<span class="line"><span>         service:</span></span>
<span class="line"><span>           name: my-service</span></span>
<span class="line"><span>           port:</span></span>
<span class="line"><span>             number: 80</span></span></code></pre></div><ul><li><p>host：指定主机域名，可以是精确匹配（例如 “myapp.address.com”）或者使用通配符来匹配（例如 “*.address.com”）。</p></li><li><p>path：指定访问请求的路径。</p></li><li><p>pathType：路径匹配方式。有三种类型：ImplementationSpecific（取决于IngressClass）、Exact（精确匹配 URL 路径，区分大小写）和 Prefix（前缀匹配，区分大小写）。通常我们使用 Prefix 类型。</p></li><li><p>backend：转发到的后端 Service，也就是部署好的应用的代理 Service。</p></li></ul><p>使用 “kubectl apply” 命令部署 Ingress，部署成功后可以查看 Ingress 信息。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl apply -f my-ingress.yaml</span></span>
<span class="line"><span>[root@k8s-master ~]# kubectl get ingress</span></span>
<span class="line"><span>NAME         CLASS   HOSTS               ADDRESS   PORTS   AGE</span></span>
<span class="line"><span>my-ingress   nginx   myapp.address.com             80      7m43s</span></span></code></pre></div><p>现在路由转发规则也创建好了，我们思考一下如何通过域名和路径访问应用。</p><h2 id="访问-ingress-controller" tabindex="-1">访问 Ingress Controller <a class="header-anchor" href="#访问-ingress-controller" aria-label="Permalink to &quot;访问 Ingress Controller&quot;">​</a></h2><p>你已经知道在 Ingress 机制中，集群外部的访问请求是由 Ingress Controller 按照规则转发到不同 Service 的，所以要访问应用 Pod，就需要访问到 Ingress Controller。而 IngressController 是由部署到 K8s 的 Deployment（包含处理流量转发的 Pod）和 Service 组成的。因此，我们实际上要访问这个 Service，从而访问到 Deployment 中的处理流量转发的 Pod。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/2.png" alt=""></a></p><p>根据以上原理，我们通过 “kubectl get svc” 命令查看 Ingress Controller 的 Service。</p><p>注意：命名空间为 “ingress-nginx”。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl get svc ingress-nginx-controller -n ingress-nginx</span></span>
<span class="line"><span>NAME                       TYPE           CLUSTER-IP      EXTERNAL-IP   PORT(S)</span></span>
<span class="line"><span>ingress-nginx-controller   LoadBalancer   10.106.241.178  &lt;​pending&gt;     80:31445/</span></span></code></pre></div><p>从结果中我们看到名称为 ingress-nginx-controller 的 Service，它的类型是 LoadBalancer。</p><p>如果集群可以使用外部的第三方负载均衡器，那么这个 Service 可以分配到一个外部 IP（EXTERNAL-IP），我们就可以把域名解析到这个 IP，然后直接通过“&lt; 域名 &gt;&lt; 路径 &gt;”方式访问 Service，从而访问到最终的应用 Pod。</p><p>如果没有外部 IP（EXTERNAL-IP），我们也可以通过 NodePort 的方式访问 Service。LoadBalancer 类型的 Service 也会自动分配一个 NodePort 端口，我们可以通过这个节点端口来访问 Service。但是，这里访问 Service 不能使用 “&lt; 节点 IP&gt;:&lt; 节点端口 &gt;” 的方式，因为Ingress 需要根据访问请求的域名和路径来转发流量，所以我们需要把域名解析到任意节点的IP，然后使用“&lt; 域名 &gt;:&lt; 节点端口 &gt;&lt; 路径 &gt;”的方式访问 Service，从而访问到最终的应用Pod。这种 NodePort 访问方式虽然简单，但是缺点就是访问时还需要输入节点端口号。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/3.png" alt=""></a></p><p>最后，如果你无法配置互联网上的域名解析，只是想在本地机器上测试规则，我们可以在自己的本地机器上配置一条域名解析。对于 Mac 系统用户，可以打开终端，编辑 “/etc/hosts” 文件，在文件末尾添加 “IP 域名”的映射规则。这样，在本地机器的浏览器中输入域名访问时，系统会优先按照 “/etc/hosts” 文件中的配置来解析 IP，从而将请求转发到集群中的相应节点上。其他系统的配置方法可以参考网上相关文档。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[steve@bogon ~]# vi /etc/hosts  # 在文件中插入域名解析规则条目</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>49.xxx.xxx.187  myapp.address.com</span></span>
<span class="line"><span># 使用你的集群中任意节点的公网 IP，以及你在 Ingress 中配置的 Host 域名</span></span></code></pre></div><p>然后你在本地机器的浏览器中输入域名和端口号，尝试一下，终于出现了我们部署在Deployment 中的应用 Nginx，也就意味着 Ingress 路由规则生效了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/4.png" alt=""></a></p><h2 id="配置-https" tabindex="-1">配置 HTTPS <a class="header-anchor" href="#配置-https" aria-label="Permalink to &quot;配置 HTTPS&quot;">​</a></h2><p>现在，一套完整的 Web 应用已经部署成功了，这套部署方案中包含了 Deployment、Service和 Ingress，最终通过 URL 访问到了我们的应用，是不是很有成就感？先别着急，我们还有一个重要的问题，那就是 HTTPS 请求。在当前的网络环境下，大部分网络访问请求都使用HTTPS 协议，因此我们需要在 Ingress 中配置一下 HTTPS 协议。</p><ul><li>HTTPS 是一种安全可靠的网络通信协议，它通过 SSL/TLS 证书实现数据加密和服务提供方身份验证。证书由权威的证书颁发机构（CA）签发。当浏览器通过 HTTPS 访问服务提供方时，它会检查服务方的证书，确保证书有效。一旦验证通过，浏览器和服务方就会使用证书中的密钥建立加密连接，从而安全地传输数据。</li></ul><p>Ingress 支持处理集群外部的 HTTPS 请求。你可以为 Ingress 配置一个 Secret 来提供SSL/TLS 的证书和私钥。用户通过 HTTPS 请求时，Ingress 会返回证书，浏览器验证通过后，就可以使用证书加密请求数据。请求到达 Ingress Controller 后，会被解密并转发到后端的 Service。</p><p>下面我就带你来动手配置 HTTPS。</p><h3 id="第一步-生成证书文件" tabindex="-1">第一步：生成证书文件 <a class="header-anchor" href="#第一步-生成证书文件" aria-label="Permalink to &quot;第一步：生成证书文件&quot;">​</a></h3><p>首先，我们需要获取证书文件，该文件可以由权威机构颁发，或者使用 OpenSSL 自签名证书。如果购买使用权威机构颁发的证书，可以在它们网站里下载服务器类型是 “Nginx” 的证书文件。如果想自签名证书，可以安装 OpenSSL 工具，使用该工具生成证书。</p><p>这里我简单介绍如何在 Linux 系统上生成自签名证书文件。你可以把我用的域名“myapp.address.com” 替换成你的域名。</p><p>在管理节点上执行以下命令来生成一个自签名证书。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1、安装 OpenSSL 工具</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openssl-devel</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2、生成一个私钥文件</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> genpkey</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -algorithm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RSA</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp.address.com.key</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3、成证书签名请求（CSR）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp.address.com.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mycsr.csr</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 你将被提示输入国家、地区、组织名称、组织单位、通用名称（通常是你的域名或服务器名称）等信息</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Country Name (2 letter code) [XX]: 国家简称，中国是 CN</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># State or Province Name (full name) []: 省份拼音</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Locality Name (eg, city) [Default City]: 城市拼音</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Organization Name (eg, company) [Default Company Ltd]: 公司英文名</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Organizational Unit Name (eg, section) []: 部门英文名</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Common Name (eg, your name or your server&#39;s hostname) []: 域名</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Email Address []: 邮箱</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># extra 额外信息不用填写</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4、使用私钥和 CSR 生成自签名证书</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -req</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -days</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 365</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mycsr.csr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -signkey</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp.address.com.key</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cer</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 这个命令会生成一个名为 certificate.crt 的自签名证书，有效期为 365 天</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 5、验证证书的内容</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">openssl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> x509</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -text</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -noout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -in</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.crt</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 6、实际部署时，需要将私钥和证书合并到一个文件中</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp.address.com.key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> certificate.crt</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp.address.com.pem</span></span></code></pre></div><p>最终生成的文件分别是 “myapp.address.com.key” 和 “myapp.address.com.pem”。</p><h3 id="第二步-部署证书-secret" tabindex="-1">第二步：部署证书 Secret <a class="header-anchor" href="#第二步-部署证书-secret" aria-label="Permalink to &quot;第二步：部署证书 Secret&quot;">​</a></h3><p>将私钥和证书文件通过 Secret 部署。之前介绍 Secret 的时候说过它的三种类型：docker-registry、generic 和 tls。这次我们将使用 tls 类型。</p><p>通过 “kubectl create” 命令创建 tls 类型的 Secret，使用证书和私钥文件的路径作为参数。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myapp-address-com-secret</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cert=./myapp.address.com.pem</span></span></code></pre></div><ul><li><p>–cert：证书文件，一般后缀名为 “.pem” 或 “.crt”，此参数需要填写证书文件的路径（绝对路径或相对路径）。</p></li><li><p>–key：私钥文件，一般后缀名为 “.key”，此参数需要填写私钥文件的路径（绝对路径或相对路径）。</p></li></ul><p>执行命令后，会在 K8s 集群里创建一个证书 Secret。</p><h3 id="第三步-在-ingress-的-yaml-文件中增加-tls-配置" tabindex="-1">第三步：在 Ingress 的 YAML 文件中增加 tls 配置 <a class="header-anchor" href="#第三步-在-ingress-的-yaml-文件中增加-tls-配置" aria-label="Permalink to &quot;第三步：在 Ingress 的 YAML 文件中增加 tls 配置&quot;">​</a></h3><p>在上面的 Ingress 规则的 YAML 文件（my-ingress.yaml）中加入 tls 属性。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># my-ingress.yaml</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>spec:</span></span>
<span class="line"><span> ingressClassName: nginx</span></span>
<span class="line"><span> tls:</span></span>
<span class="line"><span> - hosts:</span></span>
<span class="line"><span>   - myapp.address.com</span></span>
<span class="line"><span>   secretName: myapp-address-com-secret</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>重新保存 YAML 文件，部署成功后，我们再来查看一下 Ingress Controller 的 Service。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[root@k8s-master ~]# kubectl apply -f my-ingress.yaml</span></span>
<span class="line"><span>ingress.networking.k8s.io/my-ingress configured</span></span>
<span class="line"><span>[root@k8s-master ~]# kubectl get svc ingress-nginx-controller -n ingress-nginx</span></span>
<span class="line"><span>NAME                       TYPE           CLUSTER-IP       EXTERNAL-IP   PORT(S)</span></span>
<span class="line"><span>ingress-nginx-controller   LoadBalancer   10.106.241.178   &lt;​pending&gt;     80:31445</span></span></code></pre></div><p>这时，我们要注意，HTTPS 协议访问请求默认是 443 端口，也就是要访问 IngressController 中的 Service 的 443 端口，这个端口被映射到了节点的 30181 端口（443:30181/TCP），此时就可以通过本地机器的浏览器访问<a href="https://myapp.address.com:30181/" target="_blank" rel="noreferrer">https://myapp.address.com:30181/</a> URL 地址。我们就可以看到返回的 Nginx 欢迎页面了（因为我们使用了自签名证书，其实并不安全，所以浏览器通常都会有个安全提示，在提示页面中的高级按钮中点击继续就可以看到欢迎网页了）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E9%9B%B6%E5%9F%BA%E7%A1%80%E6%8B%BF%E4%B8%8B%E4%BA%91%E5%8E%9F%E7%94%9FCKA%E8%AE%A4%E8%AF%81/images/10/5.png" alt=""></a></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我介绍了 Ingress 资源对象在 K8s 集群中的作用和使用方法。</p><p>Ingress 通过定义一系列的路由规则，允许你将集群外部的 HTTP/HTTPS 请求转发到集群内不同的 Service 上。它获取到用户访问的域名和路径，然后根据规则把访问请求转发到了对应的 Service 上，然后再由 Service 把流量转发到具体的应用 Pod。Ingress 路由机制的主要组成包括 Ingress、Ingress Controller 和 Ingress Class。Ingress 定义了访问路由转发规则，Ingress Controller 负责根据这些规则将外部访问请求转发到后端的 Service，而 Ingress Class则用于解耦 Ingress 和 Ingress Controller。</p><p>K8s 官方并没有实现自己的 Ingress Controller，所以我带你一步步安装了最常用的 NginxIngress Controller，安装之后，会自动在 K8s 集群中部署 Ingress Controller 的 Deployment和 Service，同时生成一个对应的 Ingress Class。</p><p>之后，你可以通过 kubectl 命令或者 YAML 文件创建 Ingress 规则。每个规则定义了如何处理进入集群的访问请求，包含主机名（Host）和路径列表（Path），每个路径又关联一个后端服务（Backend），后端服务就是实际处理访问请求的 Service。</p><p>部署好 Ingress 规则，就可以通过 Ingress Controller 的 Service 来访问。这是一个LoadBalance 类型的 Service，如果集群支持 LoadBalance 类型，你可以把域名解析到外部IP（EXTERNAL-IP），然后通过“&lt; 域名 &gt;&lt; 路径 &gt;”访问。如果不支持 LoadBalance 类型，你可以通过 NodePort 的方式来访问，把域名解析到任意节点 IP，然后通过“&lt; 域名 &gt;:&lt; 节点端口 &gt;&lt; 路径 &gt;”访问。</p><p>最后，介绍了如何在 Ingress 上配置 HTTPS 访问，包括生成证书文件、部署证书 Secret 以及在 Ingress 的 YAML 文件中增加 tls 属性等步骤。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这就是今天的全部内容，Ingress 是 K8s 中又一个非常重要的网络资源对象，在 CKA 中也会考到相关的知识点，我给你留一道思考题。</p><p>配置 HTTPS 时，需要使用 443 端口，那么在 Ingress 规则对应的 Service 中是否需要配置443 端口，同时在 Deployment 的应用 Pod 中，容器 Nginx 是否也需要暴露 443 端口？</p><p>我希望你能实际动手实验一下，相信经过动手实践，会让你对知识的理解更加深刻。</p>`,87)])])}const d=n(l,[["render",p]]);export{k as __pageData,d as default};
